    nl: calc => `Wat er over het jaar op je rekening komt${calc}. Bruto − sociale bijdragen − inkomstenbelasting.`,
    fr: calc => `Ce qui arrive sur votre compte sur l'année${calc}. Brut − cotisations − impôt sur le revenu.`,
